Here's how you might implement a simple stack in different languages: struct Stack<T> { items: Vec<T>,
} impl<T> Stack<T> { fn new() -> Self { Stack { items: Vec::new() } } fn push(&mut self, item: T) { self.items.push(item); } fn pop(&mut self) -> Option<T> { self.items.pop() } fn is_empty(&self) -> bool { self.items.is_empty() }
} fn main() { let mut stack = Stack::new(); stack.push(1); stack.push(2); stack.push(3); while let Some(item) = stack.pop() { println!("Popped: {}", item); }
} class Stack: def __init__(self): self.items = [] def push(self, item): self.items.append(item) def pop(self): if not self.is_empty(): return self.items.pop() return None def is_empty(self): return len(self.items) == 0 # Usage
stack = Stack()
stack.push(1)
stack.push(2)
stack.push(3) while not stack.is_empty(): print(f"Popped: {stack.pop()}") class Stack { constructor() { this.items = []; } push(item) { this.items.push(item); } pop() { if (!this.isEmpty()) { return this.items.pop(); } return null; } isEmpty() { return this.items.length === 0; }
} // Usage
const stack = new Stack();
stack.push(1);
stack.push(2);
stack.push(3); while (!stack.isEmpty()) { console.log(`Popped: ${stack.pop()}`);
} package main import "fmt" type Stack struct { items []int
} func (s *Stack) Push(item int) { s.items = append(s.items, item)
} func (s *Stack) Pop() (int, bool) { if s.IsEmpty() { return 0, false } index := len(s.items) - 1 item := s.items[index] s.items = s.items[:index] return item, true
} func (s *Stack) IsEmpty() bool { return len(s.items) == 0
} func main() { stack := Stack{} stack.Push(1) stack.Push(2) stack.Push(3) for !stack.IsEmpty() { item, _ := stack.Pop() fmt.Printf("Popped: %d\n", item) }
} import java.util.ArrayList; public class StackExample { static class Stack<T> { private ArrayList<T> items = new ArrayList<>(); public void push(T item) { items.add(item); } public T pop() { if (isEmpty()) { return null; } return items.remove(items.size() - 1); } public boolean isEmpty() { return items.isEmpty(); } } public static void main(String[] args) { Stack<Integer> stack = new Stack<>(); stack.push(1); stack.push(2); stack.push(3); while (!stack.isEmpty()) { System.out.println("Popped: " + stack.pop()); } }
}

5.body:
1.1 安装与编译 在安装python3-dev和下载了pybind11源码的前提下，可以直接include pybind11头文件目录和python3头文件目录即可。cmake示例如下： set(PYTHON_TARGET_VER 3.6)
find_package(PythonInterp ${PYTHON_TARGET_VER} EXACT)
find_package(PythonLibs ${PYTHON_TARGET_VER} EXACT REQUIRED) include_directories(pybind11_include_path)
include_directories(${PYTHON_INCLUDE_DIRS}) 1.2 绑定函数 #include <pybind11/pybind11.h> int add(int i, int j) { return i + j;
} PYBIND11_MODULE(example, m) { m.doc() = "pybind11 example plugin"; // optional module docstring m.def("add", &add, "A function which adds two numbers");
} 宏PYBIND11_MODULE会创建模块初始化函数，它在Python中import模块时被调用。其参数分别是模块名，类型为py::module_的变量（m），是创建绑定的主要接口。module_::def()方法，可以生成函数的绑定。 1.2.1 关键字参数 使用py::arg可以指定函数的参数名，Python侧调用函数时可以使用关键字参数，以增加代码的可读性。 m.def("add", &add, "A function which adds two numbers", py::arg("i"), py::arg("j")); 更简洁的写法： // regular notation
m.def("add1", &add, py::arg("i"), py::arg("j"));
// shorthand
using namespace pybind11::literals;
m.def("add2", &add, "i"_a, "j"_a); Python使用示例： import example
example.add(i=1, j=2) #3L 1.2.2 参数默认值 pybind11不能自动地提取默认参数，因为它不属于函数类型信息的一部分。我们需要借助arg在绑定时指定参数默认值： m.def("add", &add, "A function which adds two numbers", py::arg("i") = 1, py::arg("j") = 2); 更简短的声明方式： // regular notation
m.def("add1", &add, py::arg("i") = 1, py::arg("j") = 2);
// shorthand
m.def("add2", &add, "i"_a=1, "j"_a=2); 1.2.3 重载函数 重载方法即拥有相同的函数名，但入参不一样的函数。 在绑定重载函数时，我们需要增加函数签名相关的信息以消除歧义。绑定多个函数到同一个Python名称，将会自动创建函数重载链。Python将会依次匹配，找到最合适的重载函数。 m.def("add", static_cast<int(*)(int, int)>(&add), "A function which adds two int numbers");
m.def("add", static_cast<double(*)(double, double)>(&add), "A function which adds two double numbers"); 如果你的编译器支持C++14，也可以使用下面的语法来转换重载函数： m.def("add", py::overload_cast<int, int>(&add), "A function which adds two int numbers");
m.def("add", py::overload_cast<double, double>(&add), "A function which adds two double numbers"); 这里，py::overload_cast仅需指定函数类型，不用给出返回值类型，以避免原语法带来的不必要的干扰(void (Pet::*))。如果是基于const的重载，需要使用py::const标识。 1.3 导出变量 我们可以使用attr函数来注册需要导出到Python模块中的C++变量。内建类型和常规对象会在指定attriutes时自动转换，也可以使用py::cast来显式转换。 PYBIND11_MODULE(example, m) { m.attr("the_answer") = 42; py::object world = py::cast("World"); m.attr("what") = world;
}
`` Python中使用如下：
​```pyhton
>>> import example
>>> example.the_answer
42
>>> example.what
'World' 1.4 绑定类或结构体 现在我们来绑定一个C++自定义数据结构Pet。定义如下： struct Pet { Pet(const std::string &name) : name(name) { } void setName(const std::string &name_) { name = name_; } const std::string &getName() const { return name; } std::string name;
}; 绑定代码如下所示： #include <pybind11/pybind11.h>
namespace py = pybind11; PYBIND11_MODULE(example, m) { py::class_<Pet>(m, "Pet") .def(py::init<const std::string &>()) .def("setName", &Pet::setName) .def("getName", &Pet::getName) .def("__repr__", [](const Pet &a) { return "<example.Pet named '" + a.name + "'>"; });
} class_会创建C++ class或 struct的绑定。init()方法用于创建绑定类的构造函数，它使用类构造函数的参数类型作为模板参数，并包装相应的构造函数。 使用print(p)打印对象信息时，默认会得到一些没用的信息。我们可以绑定一个工具函数到__repr__方法，来返回可读性好的摘要信息。在不改变Pet类的基础上，使用一个匿名函数来完成这个功能是一个不错的选择。 Python使用示例如下； >>> import example
>>> p = example.Pet("Molly")
>>> print(p)
<example.Pet named 'Molly'>
>>> p.getName()
u'Molly'
>>> p.setName("Charly")
>>> p.getName()
u'Charly' 静态成员函数需要使用class_::def_static来绑定。 1.4.1 成员函数 使用class_::def_readwrite方法可以导出公有成员变量，使用class_::def_readonly方法则可以导出只读成员。 py::class_<Pet>(m, "Pet") .def(py::init<const std::string &>()) .def_readwrite("name", &Pet::name) // ... remainder ... Python中使用示例如下： >>> p = example.Pet("Molly")
>>> p.name
u'Molly'
>>> p.name = "Charly"
>>> p.name
u'Charly' 假设Pet::name是一个私有成员变量，向外提供setter和getters方法。 class Pet {
public: Pet(const std::string &name) : name(name) { } void setName(const std::string &name_) { name = name_; } const std::string &getName() const { return name; }
private: std::string name;
}; 可以使用class_::def_property()(只读成员使用class_::def_property_readonly())来定义并私有成员，并生成相应的setter和geter方法： py::class_<Pet>(m, "Pet") .def(py::init<const std::string &>()) .def_property("name", &Pet::getName, &Pet::setName) // ... remainder ... 只写属性通过将read函数定义为nullptr来实现。 相似的方法class_::def_readwrite_static(), class_::def_readonly_static() class_::def_property_static(), class_::def_property_readonly_static()用于绑定静态变量和属性。 1.4.2 动态属性 原生的Pyhton类可以动态地获取新属性： >>> class Pet:
... name = "Molly"
...
>>> p = Pet()
>>> p.name = "Charly" # overwrite existing
>>> p.age = 2 # dynamically add a new attribute 默认情况下，从C++导出的类不支持动态属性，其可写属性必须是通过class_::def_readwrite或class_::def_property定义的。试图设置其他属性将产生错误： >>> p = example.Pet()
>>> p.name = "Charly" # OK, attribute defined in C++
>>> p.age = 2 # fail
AttributeError: 'Pet' object has no attribute 'age' 要让C++类也支持动态属性，我们需要在py::class_的构造函数添加py::dynamic_attr标识： py::class_<Pet>(m, "Pet", py::dynamic_attr()) .def(py::init<>()) .def_readwrite("name", &Pet::name); 这样，之前报错的代码就能够正常运行了。 >>> p = example.Pet()
>>> p.name = "Charly" # OK, overwrite value in C++
>>> p.age = 2 # OK, dynamically add a new attribute
>>> p.__dict__ # just like a native Python class
{'age': 2} 需要提醒一下，支持动态属性会带来小小的运行时开销。不仅仅因为增加了额外的__dict__属性，还因为处理循环引用时需要花费更多的垃圾收集跟踪花销。但是不必担心这个问题，因为原生Python类也有同样的开销。默认情况下，pybind11导出的类比原生Python类效率更高，使能动态属性也只是让它们处于同等水平而已。 1.4.3 重载方法 重载类的方法同上一节的普通函数重载，这里举个实例仅供参考： struct Pet { Pet(const std::string &name, int age) : name(name), age(age) { } void set(int age_) { age = age_; } void set(const std::string &name_) { name = name_; } std::string name; int age;
}; // method 1
py::class_<Pet>(m, "Pet") .def(py::init<const std::string &, int>()) .def("set", static_cast<void (Pet::*)(int)>(&Pet::set), "Set the pet's age") .def("set", static_cast<void (Pet::*)(const std::string &)>(&Pet::set), "Set the pet's name"); // method 2
py::class_<Pet>(m, "Pet") .def("set", py::overload_cast<int>(&Pet::set), "Set the pet's age") .def("set", py::overload_cast<const std::string &>(&Pet::set), "Set the pet's name"); 1.5 绑定枚举类型 对于C风格的枚举类型，绑定示例如下： enum Flags { Read = 4, Write = 2, Execute = 1
}; py::enum_<Flags>(m, "Flags", py::arithmetic()) .value("Read", Flags::Read) .value("Write", Flags::Write) .value("Execute", Flags::Execute) .export_values(); enum_::export_values()用来导出枚举项到父作用域，C++11的强枚举类型需要跳过这点。 枚举类型的枚举项会被导出到类__members__属性中，name属性可以返回枚举值的名称的unicode字符串，str(enum)也可以做到，但两者的实现目标不同。 1.6 接收*args和**kwargs参数 Python的函数可以接收任意数量的参数和关键字参数： def generic(*args, **kwargs): ... # do something with args and kwargs 我们也可以通过pybind11来创建这样的函数： void generic(py::args args, const py::kwargs& kwargs) { /// .. do something with args if (kwargs) /// .. do something with kwargs
} /// Binding code
m.def("generic", &generic); py::args继承自py::tuple，py::kwargs继承自py::dict。

