7.body:
3.1 继承与多态 现在有两个具有继承关系的类： struct Pet { Pet(const std::string &name) : name(name) { } std::string name;
}; struct Dog : Pet { Dog(const std::string &name) : Pet(name) { } std::string bark() const { return "woof!"; }
}; pybind11提供了两种方法来指明继承关系：1）将C++基类作为派生类class_的模板参数；2）将基类名作为class_的参数绑定到派生类。两种方法是等效的。 py::class_<Pet>(m, "Pet") .def(py::init<const std::string &>()) .def_readwrite("name", &Pet::name); // Method 1: template parameter:
py::class_<Dog, Pet /* <- specify C++ parent type */>(m, "Dog") .def(py::init<const std::string &>()) .def("bark", &Dog::bark); // Method 2: pass parent class_ object:
py::class_<Dog>(m, "Dog", pet /* <- specify Python parent type */) .def(py::init<const std::string &>()) .def("bark", &Dog::bark); 指明继承关系后，派生类实例将获得两者的字段和方法： >>> p = example.Dog("Molly")
>>> p.name
u'Molly'
>>> p.bark()
u'woof!' 上面的例子是一个常规非多态的继承关系，表现在Python就是： // 返回一个指向派生类的基类指针
m.def("pet_store", []() { return std::unique_ptr<Pet>(new Dog("Molly")); }); >>> p = example.pet_store()
>>> type(p) # `Dog` instance behind `Pet` pointer
Pet # no pointer downcasting for regular non-polymorphic types
>>> p.bark()
AttributeError: 'Pet' object has no attribute 'bark' pet_store函数返回了一个Dog实例，但由于基类并非多态类型，Python只识别到了Pet。在C++中，一个类至少有一个虚函数才会被视为多态类型。pybind11会自动识别这种多态机制。 struct PolymorphicPet { virtual ~PolymorphicPet() = default;
}; struct PolymorphicDog : PolymorphicPet { std::string bark() const { return "woof!"; }
}; // Same binding code
py::class_<PolymorphicPet>(m, "PolymorphicPet");
py::class_<PolymorphicDog, PolymorphicPet>(m, "PolymorphicDog") .def(py::init<>()) .def("bark", &PolymorphicDog::bark); // Again, return a base pointer to a derived instance
m.def("pet_store2", []() { return std::unique_ptr<PolymorphicPet>(new PolymorphicDog); }); >>> p = example.pet_store2()
>>> type(p)
PolymorphicDog # automatically downcast
>>> p.bark()
u'woof!' pybind11会自动地将一个指向多态基类的指针，向下转型为实际的派生类类型。这和C++常见的情况不同，我们不仅可以访问基类的虚函数，还能获取到通过基类看不到的，具体的派生类的方法和属性。 3.2 Python继承C++类 对于一个拥有纯虚函数的类，使用常规的绑定方法并在Python中直接继承它会报错，因为纯虚基类是不可构造的。 class Animal {
public: virtual ~Animal() { } virtual std::string go(int n_times) = 0;
}; class Dog : public Animal {
public: std::string go(int n_times) override { std::string result; for (int i=0; i<n_times; ++i) result += "woof! "; return result; }
}; std::string call_go(Animal *animal) { return animal->go(3);
} PYBIND11_MODULE(example, m) { py::class_<Animal>(m, "Animal") .def("go", &Animal::go); py::class_<Dog, Animal>(m, "Dog") .def(py::init<>()); m.def("call_go", &call_go);
} 这样绑定之后，用户在Python中继承实现Animal会报错，提示"No constructor defined!"。 这时，我们需要定义一个新的Animal类作为辅助跳板： class PyAnimal : public Animal {
public: /* Inherit the constructors */ using Animal::Animal; /* Trampoline (need one for each virtual function) */ std::string go(int n_times) override { PYBIND11_OVERRIDE_PURE( std::string, /* Return type */ Animal, /* Parent class */ go, /* Name of function in C++ (must match Python name) */ n_times /* Argument(s) */ ); }
}; 定义纯虚函数时需要使用PYBIND11_OVERRIDE_PURE宏，而有默认实现的虚函数则使用PYBIND11_OVERRIDE。PYBIND11_OVERRIDE_PURE_NAME 和PYBIND11_OVERRIDE_NAME 宏的功能类似，主要用于C函数名和Python函数名不一致的时候。以__str__为例： std::string toString() override { PYBIND11_OVERRIDE_NAME( std::string, // Return type (ret_type) Animal, // Parent class (cname) "__str__", // Name of method in Python (name) toString, // Name of function in C++ (fn) );
} Animal类的绑定代码也需要一些微调： PYBIND11_MODULE(example, m) { py::class_<Animal, PyAnimal /* <--- trampoline*/>(m, "Animal") .def(py::init<>()) .def("go", &Animal::go); py::class_<Dog, Animal>(m, "Dog") .def(py::init<>()); m.def("call_go", &call_go);
} pybind11通过向class_指定额外的模板参数PyAnimal，让我们可以在Python中继承Animal类。 接下来，我们可以像往常一样定义构造函数。绑定时我们需要使用真实类，而不是辅助类。 py::class_<Animal, PyAnimal /* <--- trampoline*/>(m, "Animal"); .def(py::init<>()) .def("go", &PyAnimal::go); /* <--- THIS IS WRONG, use &Animal::go */ 下面的Python代码展示了我们继承并重载了Animal::go方法，并通过虚函数来调用它： from example import *
d = Dog()
call_go(d) # u'woof! woof! woof! '
class Cat(Animal): def go(self, n_times): return "meow! " * n_times c = Cat()
call_go(c) # u'meow! meow! meow! ' 如果你在派生的Python类中自定义了一个构造函数，你必须保证显示调用C++构造函数(通过__init__)，不管它是否为默认构造函数。否则，实例属于C++那部分的内存就未初始化，可能导致未定义行为。在pybind11 2.6版本中，这种错误将会抛出TypeError异常。 class Dachshund(Dog): def __init__(self, name): Dog.__init__(self) # Without this, a TypeError is raised. self.name = name def bark(self): return "yap!" 注意必须显式地调用__init__，而不应该使用supper()。在一些简单的线性继承中，supper()或许可以正常工作；一旦你混合Python和C++类使用多重继承，由于Python MRO和C++的机制，一切都将崩溃。 3.3 虚函数与继承 综合考虑虚函数与继承时，你需要为每个你允许在Python派生类中重载的方法提供重载方式。下面我们扩展Animal和Dog来举例： class Animal {
public: virtual std::string go(int n_times) = 0; virtual std::string name() { return "unknown"; }
};
class Dog : public Animal {
public: std::string go(int n_times) override { std::string result; for (int i=0; i<n_times; ++i) result += bark() + " "; return result; } virtual std::string bark() { return "woof!"; }
}; 上节涉及到的Animal辅助类仍是必须的，为了让Python代码能够继承Dog类，我们也需要为Dog类增加一个跳板类，来实现bark()和继承自Animal的go()、name()等重载方法（即便Dog类并不直接重载name方法）。 class PyAnimal : public Animal {
public: using Animal::Animal; // Inherit constructors std::string go(int n_times) override { PYBIND11_OVERRIDE_PURE(std::string, Animal, go, n_times); } std::string name() override { PYBIND11_OVERRIDE(std::string, Animal, name, ); }
};
class PyDog : public Dog {
public: using Dog::Dog; // Inherit constructors std::string go(int n_times) override { PYBIND11_OVERRIDE(std::string, Dog, go, n_times); } std::string name() override { PYBIND11_OVERRIDE(std::string, Dog, name, ); } std::string bark() override { PYBIND11_OVERRIDE(std::string, Dog, bark, ); }
}; 注意到name()和bark()尾部的逗号，这用来说明辅助类的函数不带任何参数。当函数至少有一个参数时，应该省略尾部的逗号。 注册一个继承已经在pybind11中注册的带虚函数的类，同样需要为其添加辅助类，即便它没有定义或重载任何虚函数： class Husky : public Dog {};
class PyHusky : public Husky {
public: using Husky::Husky; // Inherit constructors std::string go(int n_times) override { PYBIND11_OVERRIDE_PURE(std::string, Husky, go, n_times); } std::string name() override { PYBIND11_OVERRIDE(std::string, Husky, name, ); } std::string bark() override { PYBIND11_OVERRIDE(std::string, Husky, bark, ); }
}; 我们可以使用模板辅助类将简化这类重复的绑定工作，这对有多个虚函数的基类尤其有用： template <class AnimalBase = Animal> class PyAnimal : public AnimalBase {
public: using AnimalBase::AnimalBase; // Inherit constructors std::string go(int n_times) override { PYBIND11_OVERRIDE_PURE(std::string, AnimalBase, go, n_times); } std::string name() override { PYBIND11_OVERRIDE(std::string, AnimalBase, name, ); }
};
template <class DogBase = Dog> class PyDog : public PyAnimal<DogBase> {
public: using PyAnimal<DogBase>::PyAnimal; // Inherit constructors // Override PyAnimal's pure virtual go() with a non-pure one: std::string go(int n_times) override { PYBIND11_OVERRIDE(std::string, DogBase, go, n_times); } std::string bark() override { PYBIND11_OVERRIDE(std::string, DogBase, bark, ); }
}; 这样，我们只需要一个辅助方法来定义虚函数和纯虚函数的重载了。只是这样编译器就需要生成许多额外的方法和类。 下面我们在pybind11中注册这些类： py::class_<Animal, PyAnimal<>> animal(m, "Animal");
py::class_<Dog, Animal, PyDog<>> dog(m, "Dog");
py::class_<Husky, Dog, PyDog<Husky>> husky(m, "Husky");
// ... add animal, dog, husky definitions 注意，Husky不需要一个专门的辅助类，因为它没定义任何新的虚函数和纯虚函数的重载。 Python中的使用示例： class ShihTzu(Dog): def bark(self): return "yip!" 3.4 非公有析构函数 如果一个类拥有私有或保护的析构函数（例如单例类），通过pybind11绑定类时编译器将会报错。本质的问题是std::unique_ptr智能指针负责管理实例的生命周期需要引用析构函数，即便没有资源需要回收。Pybind11提供了辅助类py::nodelete来禁止对析构函数的调用。这种情况下，C++侧负责析构对象避免内存泄漏就十分重要。 /* ... definition ... */ class MyClass {
private: ~MyClass() { }
}; /* ... binding code ... */ py::class_<MyClass, std::unique_ptr<MyClass, py::nodelete>>(m, "MyClass") .def(py::init<>()) 3.5 隐式转换 假设项目中有A和B两个类型，A可以直接转换为B。 py::class_<A>(m, "A") /// ... members ... py::class_<B>(m, "B") .def(py::init<A>()) /// ... members ... m.def("func", [](const B &) { /* .... */ }
); 如果想func函数传入A类型的参数a，Pyhton侧需要这样写func(B(a))，而C++则可以直接使用func(a)，自动将A类型转换为B类型。 这种情形下（B有一个接受A类型参数的构造函数），我们可以使用如下声明来让Python侧也支持类似的隐式转换： py::implicitly_convertible<A, B>(); 3.6 重载操作符 假设有这样一个类Vector2，它通过重载操作符实现了向量加法和标量乘法。 class Vector2 {
public: Vector2(float x, float y) : x(x), y(y) { } Vector2 operator+(const Vector2 &v) const { return Vector2(x + v.x, y + v.y); } Vector2 operator*(float value) const { return Vector2(x * value, y * value); } Vector2& operator+=(const Vector2 &v) { x += v.x; y += v.y; return *this; } Vector2& operator*=(float v) { x *= v; y *= v; return *this; } friend Vector2 operator*(float f, const Vector2 &v) { return Vector2(f * v.x, f * v.y); } std::string toString() const { return "[" + std::to_string(x) + ", " + std::to_string(y) + "]"; }
private: float x, y;
}; 操作符绑定代码如下： #include <pybind11/operators.h> PYBIND11_MODULE(example, m) { py::class_<Vector2>(m, "Vector2") .def(py::init<float, float>()) .def(py::self + py::self) .def(py::self += py::self) .def(py::self *= float()) .def(float() * py::self) .def(py::self * float()) .def(-py::self) .def("__repr__", &Vector2::toString);
} .def(py::self * float())是如下代码的简短标记： .def("__mul__", [](const Vector2 &a, float b) { return a * b;
}, py::is_operator()) 3.7 深拷贝支持 Python通常在赋值中使用引用。有时需要一个真正的拷贝，以防止修改所有的拷贝实例。copy模块提供了这样的拷贝能力。 在Python3中，带pickle支持的类自带深拷贝能力。但是，自定义__copy__和__deepcopy__方法能够提高拷贝的性能。在Python2.7中，由于pybind11只支持cPickle，要想实现深拷贝，自定义这两个方法必须实现。 对于一些简单的类，可以使用拷贝构造函数来实现深拷贝。如下所示： py::class_<Copyable>(m, "Copyable") .def("__copy__", [](const Copyable &self) { return Copyable(self); }) .def("__deepcopy__", [](const Copyable &self, py::dict) { return Copyable(self); }, "memo"_a); Note: 本例中不会复制动态属性。 3.8 多重继承 pybind11支持绑定多重继承的类，只需在将所有基类作为class_的模板参数即可： py::class_<MyType, BaseType1, BaseType2, BaseType3>(m, "MyType") ... 基类间的顺序任意，甚至可以穿插使用别名或者holder类型，pybind11能够自动识别它们。唯一的要求就是第一个模板参数必须是类型本身。 允许Python中定义的类继承多个C++类，也允许混合继承C++类和Python类。 有一个关于该特性实现的警告：当仅指定一个基类，实际上有多个基类时，pybind11会认为它并没有使用多重继承，这将导致未定义行为。对于这个问题，我们可以在类构造函数中添加multiple_inheritance的标识。 py::class_<MyType, BaseType2>(m, "MyType", py::multiple_inheritance()); 当模板参数列出了多个基类时，无需使用该标识。 3.9 绑定protected成员函数 通常不可能向Python公开protected 成员函数： class A {
protected: int foo() const { return 42; }
}; py::class_<A>(m, "A") .def("foo", &A::foo); // error: 'foo' is a protected member of 'A' 因为非公有成员函数意味着外部不可调用。但我们还是希望在Python派生类中使用protected 函数。我们可以通过下面的方式来实现： class A {
protected: int foo() const { return 42; }
}; class Publicist : public A { // helper type for exposing protected functions
public: using A::foo; // inherited with different access modifier
}; py::class_<A>(m, "A") // bind the primary class .def("foo", &Publicist::foo); // expose protected methods via the publicist 因为 &Publicist::foo 和&A::foo 准确地说是同一个函数（相同的签名和地址），仅仅是获取方式不同。 Publicist 的唯一意图，就是将函数的作用域变为public。 如果是希望公开在Python侧重载的 protected虚函数，可以将publicist pattern与之前提到的trampoline相结合： class A {
public: virtual ~A() = default; protected: virtual int foo() const { return 42; }
}; class Trampoline : public A {
public: int foo() const override { PYBIND11_OVERRIDE(int, A, foo, ); }
}; class Publicist : public A {
public: using A::foo;
}; py::class_<A, Trampoline>(m, "A") // <-- `Trampoline` here .def("foo", &Publicist::foo); // <-- `Publicist` here, not `Trampoline`! 3.10 绑定final类 在C++11中，我们可以使用findal关键字来确保一个类不被继承。py::is_final属性则可以用来确保一个类在Python中不被继承。底层的C++类型不需要定义为final。 class IsFinal final {}; py::class_<IsFinal>(m, "IsFinal", py::is_final()); 在Python中试图继承这个类，将导致错误： class PyFinalChild(IsFinal): pass TypeError: type 'IsFinal' is not an acceptable base type

